The manifold $M$ is said to be recurrent \cite{Wa50} if
\begin{equation}\label{kn}
\nabla R = \Pi \otimes R \ \ \mbox{($\otimes$ denotes the tensor product)}
\end{equation}
$$(\mbox{or locally, } R_{ijkl,m}=\Pi_m R_{ijkl}, \ \ \mbox{where `,' denotes the covariant derivative})$$
holds on $\{x\in M : \nabla R \neq 0 \,\,\mbox{at}\,\, x\}$ for an 1-form $\Pi\in\chi^*(M)$, called the associated 1-form of the recurrent structure. Such an $n$-dimensional manifold is denoted by $K_{n}$.

The manifold $M$ is said to be quasi generalized recurrent \cite{SR10}, hyper generalized recurrent \cite{SP10}, weakly generalized recurrent \cite{SR11} and super generalized recurrent respectively if the condition
\begin{equation}\label{qgkn}
\nabla R = \Pi \otimes R + \Psi \otimes \left[g\wedge (g + \eta\otimes\eta)\right],
\end{equation}

\begin{equation}\label{hgkn}
\nabla R = \Pi \otimes R + \Psi \otimes g\wedge S,
\end{equation}

\begin{equation}\label{wgkn}
\nabla R = \Pi \otimes R + \Phi \otimes S\wedge S \ \ \mbox{and}
\end{equation}

\begin{equation}\label{sgkn}
\nabla R = \Pi \otimes R + \Phi \otimes S\wedge S + \Psi \otimes g\wedge S + \Theta \otimes g\wedge g
\end{equation}

holds respectively on $\{x\in M:\nabla R \neq \xi \otimes R \,\,\mbox{at}\,\, x\ \forall\ \xi \in \chi^*(M)\}  \subset M$ for some $\Pi$, $\Phi$, $\Psi$, $\Theta$ and $\eta \in \chi^*(M)$, called the associated 1-forms.

\label{thm4.1}
Let $M^n = \overline M^p \times_f \widetilde M^{n-p}$ be a warped product manifold. Then $M$ is a $SGK_n$ with $(\Pi,\Phi,\Psi,\Theta)$ if and only if the following conditions hold simultaneously

\begin{eqnarray}\label{eq4.1}
\left\{
\begin{array}{l}
(i) \overline\nabla\overline R = \overline \Pi \otimes \overline R + \overline \Phi \otimes \overline S \wedge \overline S 
																		+ \overline \Psi \otimes \overline g\wedge \overline S 
																		+ \overline \Theta \otimes \overline g \wedge \overline g\\
								\hspace{0.5in} - 2(n-p)\overline \Phi \otimes \overline S \wedge T + (n-p)^2\overline \Phi \otimes T\wedge T
																		- (n-p)\overline \Psi \otimes \overline g \wedge T,\\
(ii) -\widetilde \Pi \otimes \overline R = \widetilde \Phi \otimes \overline S \wedge \overline S
						+\widetilde \Psi \otimes \overline g \wedge \overline S + \widetilde \Theta \otimes \overline g \wedge \overline g\\
 \hspace{0.9in}	- 2(n-p)\widetilde \Phi \otimes \overline S \wedge T + (n-p)^2\widetilde \Phi \otimes T \wedge T
 					- (n-p)\widetilde \Psi \otimes \overline g \wedge T,
\end{array}
\right.
\end{eqnarray}

\begin{eqnarray}\label{eq4.2}
\left\{
\begin{array}{l}
(i) -(df + f \overline \Pi)\otimes \widetilde R = \overline \Phi \otimes \widetilde S \wedge \widetilde S 
																							+ (2 Q \overline \Phi + f\overline \Psi) \otimes \widetilde g \wedge \widetilde S\\
															\hspace{1.35in}+ (-\frac{1}{2} f^2(P \overline \Pi + dP) + Q^2 \overline \Phi + f Q \overline \Psi
																							+ f^2\overline \Theta) \otimes \widetilde g \wedge \widetilde g,\\
(ii) f \widetilde\nabla\widetilde R = f \widetilde \Pi \otimes \widetilde R 
																						+ \widetilde \Phi \otimes \widetilde S \wedge \widetilde S
																						+ (Q \widetilde \Phi + f\widetilde \Psi) \otimes \widetilde g \wedge \widetilde S\\ 
															\hspace{0.7in}+ (-\frac{1}{2} f^2 P \widetilde \Pi + Q^2 \widetilde \Phi + f Q \widetilde \Psi 
																								+ f^2 \widetilde \Theta) \otimes \widetilde g \wedge \widetilde g,\\
\end{array}
\right.
\end{eqnarray}

\begin{eqnarray}\label{eq4.3}
\left\{
\begin{array}{l}
(i) \left[2 \overline \Phi\otimes(\overline S - (n-p)T) + \overline \Psi\otimes \overline g\right]\otimes \widetilde S =\\
					\hspace{0.1in} -[f(\overline \nabla T - \overline \Pi\otimes T)+ (2Q \overline \Phi+ f\overline \Psi)
					\otimes (\overline S - (n-p)T) + (Q\overline \Psi + 2f \overline \Theta )\otimes \overline g] \otimes \widetilde g,\\
(ii) \left[2 \widetilde \Phi\otimes(\overline S -(n-p)T) +\widetilde \Psi\otimes \overline g\right]\otimes\widetilde S=\\
							\hspace{0.2in} -[-f\widetilde \Pi\otimes T+ (2Q \widetilde \Phi+ f\widetilde \Psi)\otimes 
								(\overline S - (n-p)T) + (Q\widetilde \Psi + 2f \widetilde \Theta )\otimes \overline g] \otimes \widetilde g,\\
\end{array}
\right.
\end{eqnarray}

\begin{eqnarray}\label{eq4.4}
\left\{
\begin{array}{l}
(i) f^d R_{abcd} = -(f_a T_{bc}-f_b T_{ac}) \ \ \mbox{and}\\
(ii) df\otimes \widetilde R = f^2 \Theta P\otimes \widetilde G.\\
\end{array}
\right.
\end{eqnarray}
